package am.ik.yavi.core;

import am.ik.yavi.fn.Combining12;
import am.ik.yavi.fn.Function12;
import am.ik.yavi.fn.Validation;
import org.jspecify.annotations.Nullable;

/**
 * A {@link Combining12} of {@link Validated} results, whose {@link #apply(Function12)}
 * returns a {@link Validated}.
 *
 * <p>
 * It is returned by {@link ValidatedCombining11#combine(Validation)}.
 *
 * <p>
 * Generated by <a href=
 * "https://github.com/making/yavi/blob/develop/scripts/generate-applicative.sh">generate-applicative.sh</a>.
 *
 * @param <T1> the value type of validation 1
 * @param <T2> the value type of validation 2
 * @param <T3> the value type of validation 3
 * @param <T4> the value type of validation 4
 * @param <T5> the value type of validation 5
 * @param <T6> the value type of validation 6
 * @param <T7> the value type of validation 7
 * @param <T8> the value type of validation 8
 * @param <T9> the value type of validation 9
 * @param <T10> the value type of validation 10
 * @param <T11> the value type of validation 11
 * @param <T12> the value type of validation 12
 * @since 0.18.0
 */
public class ValidatedCombining12<T1 extends @Nullable Object, T2 extends @Nullable Object, T3 extends @Nullable Object, T4 extends @Nullable Object, T5 extends @Nullable Object, T6 extends @Nullable Object, T7 extends @Nullable Object, T8 extends @Nullable Object, T9 extends @Nullable Object, T10 extends @Nullable Object, T11 extends @Nullable Object, T12 extends @Nullable Object>
		extends Combining12<ConstraintViolation, T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, T12> {

	/**
	 * Creates a combination of the given validation results.
	 * @param v1 validation 1
	 * @param v2 validation 2
	 * @param v3 validation 3
	 * @param v4 validation 4
	 * @param v5 validation 5
	 * @param v6 validation 6
	 * @param v7 validation 7
	 * @param v8 validation 8
	 * @param v9 validation 9
	 * @param v10 validation 10
	 * @param v11 validation 11
	 * @param v12 validation 12
	 */
	public ValidatedCombining12(Validated<T1> v1, Validated<T2> v2, Validated<T3> v3, Validated<T4> v4,
			Validated<T5> v5, Validated<T6> v6, Validated<T7> v7, Validated<T8> v8, Validated<T9> v9,
			Validated<T10> v10, Validated<T11> v11, Validated<T12> v12) {
		super(v1, v2, v3, v4, v5, v6, v7, v8, v9, v10, v11, v12);
	}

	/**
	 * Applies the given function to the validated values if all of the combined
	 * validations are successful. Otherwise the violations of all failed validations are
	 * accumulated in the order of the combined validations and the function is not
	 * invoked.
	 * @param f the function that receives the validated values
	 * @param <R> the type of the result
	 * @return the successful result of the function or the accumulated violations
	 */
	@Override
	public <R extends @Nullable Object> Validated<R> apply(
			Function12<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, T12, R> f) {
		return Validated.of(super.apply(f));
	}

	/**
	 * Returns a combination that also includes the given validation. The validation is
	 * appended after the existing ones, which determines the order of accumulated
	 * violations.
	 * @param v13 the validation to add
	 * @param <T13> the value type of the added validation
	 * @return the combination of 13 validations
	 */
	@Override
	public <T13 extends @Nullable Object> ValidatedCombining13<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, T12, T13> combine(
			Validation<ConstraintViolation, T13> v13) {
		return new ValidatedCombining13<>(Validated.of(v1), Validated.of(v2), Validated.of(v3), Validated.of(v4),
				Validated.of(v5), Validated.of(v6), Validated.of(v7), Validated.of(v8), Validated.of(v9),
				Validated.of(v10), Validated.of(v11), Validated.of(v12), Validated.of(v13));
	}

}
